UPDATE questions
SET normalized_content_hash = encode(
  digest(lower(trim(regexp_replace(content, '\\s+', ' ', 'g'))), 'sha256'),
  'hex'
)
WHERE id = ANY(ARRAY[
  '00000000-0000-0000-0000-000000000801'::uuid,
  '00000000-0000-0000-0000-000000000802'::uuid,
  '00000000-0000-0000-0000-000000000803'::uuid,
  '00000000-0000-0000-0000-000000000804'::uuid,
  '00000000-0000-0000-0000-000000000805'::uuid,
  '00000000-0000-0000-0000-000000000806'::uuid,
  '00000000-0000-0000-0000-000000000807'::uuid,
  '00000000-0000-0000-0000-000000000808'::uuid,
  '00000000-0000-0000-0000-000000000809'::uuid,
  '00000000-0000-0000-0000-000000000810'::uuid
]) AND normalized_content_hash IS NULL;
